IF DB_ID(N'HRMDB') IS NULL CREATE DATABASE HRMDB;
GO
USE HRMDB;
GO
IF OBJECT_ID('dbo.BangLuong','U') IS NOT NULL DROP TABLE dbo.BangLuong;
IF OBJECT_ID('dbo.BangChamCong','U') IS NOT NULL DROP TABLE dbo.BangChamCong;
IF OBJECT_ID('dbo.NhanVien','U') IS NOT NULL DROP TABLE dbo.NhanVien;
IF OBJECT_ID('dbo.PhongBan','U') IS NOT NULL DROP TABLE dbo.PhongBan;
CREATE TABLE PhongBan(MaPB INT IDENTITY(1,1) PRIMARY KEY,TenPB NVARCHAR(100) NOT NULL,Mota NVARCHAR(255));
CREATE TABLE NhanVien(MaNV INT IDENTITY(1,1) PRIMARY KEY,HoTen NVARCHAR(100) NOT NULL,NgaySinh DATETIME NULL,CCCD VARCHAR(20) UNIQUE,MaPB INT NOT NULL,LuongCoBan DECIMAL(18,2) NOT NULL CHECK(LuongCoBan>0),HeSoLuong FLOAT NOT NULL DEFAULT 1.0,FOREIGN KEY(MaPB) REFERENCES PhongBan(MaPB));
CREATE TABLE BangChamCong(MaCong INT IDENTITY(1,1) PRIMARY KEY,MaNV INT NOT NULL,ThangNam VARCHAR(7) NOT NULL,SoNgayCong FLOAT NOT NULL CHECK(SoNgayCong>=0 AND SoNgayCong<=31),SoGioOT FLOAT NOT NULL DEFAULT 0 CHECK(SoGioOT>=0),FOREIGN KEY(MaNV) REFERENCES NhanVien(MaNV),CONSTRAINT UQ_BangChamCong UNIQUE(MaNV,ThangNam));
CREATE TABLE BangLuong(MaLuong INT IDENTITY(1,1) NOT NULL,MaNV INT NOT NULL,ThangNam VARCHAR(7) NOT NULL,ThucLinh DECIMAL(18,2) NOT NULL,PRIMARY KEY(MaNV,ThangNam),UNIQUE(MaLuong),FOREIGN KEY(MaNV) REFERENCES NhanVien(MaNV));
